-- MySQL 8 read-only validation. Run after 06. All samples are restricted to SIM20260918 prefix.
-- Snapshot date is fixed; do not use CURDATE() to shift cohort meaning.
SET @snapshot_date = DATE('2026-09-18');
WITH b AS (SELECT * FROM `indiv_cust`.`L_INDVCST_LABEL` WHERE CUST_ID LIKE 'SIM20260918%') SELECT COUNT(*) AS row_count, COUNT(DISTINCT CUST_ID) AS distinct_ids,
SUM(CUR_POINT_AUM) AS total_aum, AVG(CUR_POINT_AUM) AS avg_aum,
MIN(CUR_POINT_AUM) AS min_aum, MAX(CUR_POINT_AUM) AS max_aum FROM b;
WITH b AS (SELECT * FROM `indiv_cust`.`L_INDVCST_LABEL` WHERE CUST_ID LIKE 'SIM20260918%'), ranked AS (SELECT CUR_POINT_AUM, ROW_NUMBER() OVER(ORDER BY CUR_POINT_AUM) rn, COUNT(*) OVER() n FROM b)
SELECT AVG(CUR_POINT_AUM) AS median_aum FROM ranked WHERE rn IN (FLOOR((n+1)/2),FLOOR((n+2)/2));
WITH b AS (SELECT * FROM `indiv_cust`.`L_INDVCST_LABEL` WHERE CUST_ID LIKE 'SIM20260918%') SELECT CUST_ID FROM b WHERE
 ROUND(CUR_POINT_AUM,2) <> ROUND(CUR_DEPOSIT_BALANCE+CUR_WMP_BALANCE+CUR_FUND_BALANCE+CUR_GOLD_BALANCE+CUR_TREASURY_BOND_BALANCE+CUR_TRUST_BALANCE+CUR_VALUE_TYPE_INSURANCE_BALANCE,2)
 OR ROUND(CUR_DEPOSIT_BALANCE,2) <> ROUND(CUR_DEMAND_DEPOSIT_BALANCE+CUR_TIME_DEPOSIT_BALANCE,2)
 OR CUR_HOLDING_WMP_FLAG <> (CUR_WMP_BALANCE>0) OR CUR_HOLDING_FUND_FLAG <> (CUR_FUND_BALANCE>0);
-- Expected empty result above.
WITH b AS (SELECT * FROM `indiv_cust`.`L_INDVCST_LABEL` WHERE CUST_ID LIKE 'SIM20260918%') SELECT CUR_CUST_LEVEL, CUR_WMP_RISK_ASSESSMENT_LEVEL,
 COUNT(*) n, AVG(CUR_HOLDING_WMP_FLAG) wmp_rate, AVG(CUR_HOLDING_FUND_FLAG) fund_rate, AVG(((CUR_DEPOSIT_BALANCE>0)+(CUR_WMP_BALANCE>0)+(CUR_FUND_BALANCE>0)+(CUR_GOLD_BALANCE>0)+(CUR_TREASURY_BOND_BALANCE>0)+(CUR_TRUST_BALANCE>0)+(CUR_VALUE_TYPE_INSURANCE_BALANCE>0))) mean_product_types
 FROM b GROUP BY CUR_CUST_LEVEL,CUR_WMP_RISK_ASSESSMENT_LEVEL;
WITH b AS (SELECT * FROM `indiv_cust`.`L_INDVCST_LABEL` WHERE CUST_ID LIKE 'SIM20260918%') SELECT CUR_CORE_CM_LEVEL1_BRANCH,COUNT(*) n,SUM(CUR_POINT_AUM) aum,
 AVG(CUR_HOLDING_WMP_FLAG) wmp_rate,AVG(((CUR_DEPOSIT_BALANCE>0)+(CUR_WMP_BALANCE>0)+(CUR_FUND_BALANCE>0)+(CUR_GOLD_BALANCE>0)+(CUR_TREASURY_BOND_BALANCE>0)+(CUR_TRUST_BALANCE>0)+(CUR_VALUE_TYPE_INSURANCE_BALANCE>0))) mean_product_types FROM b GROUP BY CUR_CORE_CM_LEVEL1_BRANCH;
-- Golden cohort: cumulative DIFF-NAME interbank inflow, not all transfer inflow or single maximum.
WITH b AS (SELECT * FROM `indiv_cust`.`L_INDVCST_LABEL` WHERE CUST_ID LIKE 'SIM20260918%') SELECT CUST_ID,CUR_POINT_AUM,LAST_30_DAYS_DIFF_NAME_INTERBANK_TRANSFER_IN_AMT,
 CUR_DEPOSIT_BALANCE/NULLIF(CUR_POINT_AUM,0) deposit_ratio FROM b
 WHERE LAST_30_DAYS_DIFF_NAME_INTERBANK_TRANSFER_IN_AMT>=500000 AND CUR_HOLDING_WMP_FLAG=0
 AND CUR_WMP_RISK_ASSESSMENT_LEVEL IN ('C3','C4','C5');
WITH b AS (SELECT * FROM `indiv_cust`.`L_INDVCST_LABEL` WHERE CUST_ID LIKE 'SIM20260918%') SELECT COUNT(*) n,SUM(NEXT_TIME_DEPOSIT_LATEST_MATURITY_AMT) nearest_maturity_amount
 FROM b WHERE NEXT_TIME_DEPOSIT_LATEST_MAT_DATE>@snapshot_date AND NEXT_TIME_DEPOSIT_LATEST_MAT_DATE<=DATE_ADD(@snapshot_date,INTERVAL 30 DAY)
 AND NEXT_TIME_DEPOSIT_LATEST_MATURITY_AMT>=100000;
-- This is nearest recorded maturity, not all future 30-day maturities.
WITH b AS (SELECT * FROM `indiv_cust`.`L_INDVCST_LABEL` WHERE CUST_ID LIKE 'SIM20260918%') SELECT COUNT(*) n,AVG(CUR_MONTH_APP_LOGIN_DAYS/18.0) current_daily_login_rate,
 AVG(PREV_3_MONTHS_APP_LOGIN_DAYS/92.0) prior_daily_login_rate FROM b
 WHERE LAST_MONTH_PAYROLL_AMT>0 AND CUR_MONTH_PAYROLL_AMT<LAST_MONTH_PAYROLL_AMT*0.7
 AND LAST_MONTH_PAYROLL_AMT<PREV_6_MONTHS_AVG_PAYROLL_AMT*0.85;
WITH b AS (SELECT * FROM `indiv_cust`.`L_INDVCST_LABEL` WHERE CUST_ID LIKE 'SIM20260918%') SELECT COUNT(*) n,SUM(CUR_POINT_AUM) aum FROM b
 WHERE CUR_POINT_AUM>=1000000 AND ((CUR_DEPOSIT_BALANCE>0)+(CUR_WMP_BALANCE>0)+(CUR_FUND_BALANCE>0)+(CUR_GOLD_BALANCE>0)+(CUR_TREASURY_BOND_BALANCE>0)+(CUR_TRUST_BALANCE>0)+(CUR_VALUE_TYPE_INSURANCE_BALANCE>0))<=2;
-- All results should be 0; NULL is allowed and not treated as invalid.
SELECT 'REGISTERED_RESIDENCE_WHETHER_OUR_BANK_BUSINESS_AREA_FLAG' field_name, COUNT(*) invalid_count FROM `indiv_cust`.`L_INDVCST_LABEL` b WHERE CUST_ID LIKE 'SIM20260918%' AND b.`REGISTERED_RESIDENCE_WHETHER_OUR_BANK_BUSINESS_AREA_FLAG` IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `indiv_cust`.`L_INDVCST_LABEL_CODE_MAP` m WHERE m.tag_name_en='REGISTERED_RESIDENCE_WHETHER_OUR_BANK_BUSINESS_AREA_FLAG' AND m.tag_code=CAST(b.`REGISTERED_RESIDENCE_WHETHER_OUR_BANK_BUSINESS_AREA_FLAG` AS CHAR))
UNION ALL
