-- Opportunity rule v1; derived output only, no base-table opportunity label.
WITH b AS (SELECT * FROM `indiv_cust`.`L_INDVCST_LABEL` WHERE CUST_ID LIKE 'SIM20260918%'), components AS (
 SELECT b.*,
 LEAST(25,GREATEST(0,25*LOG10(1+CUR_POINT_AUM/10000)/LOG10(1001))) value_score,
 CASE WHEN LAST_30_DAYS_DIFF_NAME_INTERBANK_TRANSFER_IN_AMT>=500000 THEN 25
 WHEN NEXT_TIME_DEPOSIT_LATEST_MAT_DATE>@snapshot_date AND NEXT_TIME_DEPOSIT_LATEST_MAT_DATE<=DATE_ADD(@snapshot_date,INTERVAL 30 DAY) AND NEXT_TIME_DEPOSIT_LATEST_MATURITY_AMT>=100000 THEN 18
 WHEN CUR_MONTH_PAYROLL_AMT>0 THEN 8 ELSE 0 END event_score,
 (CASE WHEN CUR_HOLDING_WMP_FLAG=0 THEN 20 WHEN CUR_WMP_BALANCE/NULLIF(CUR_POINT_AUM,0)<0.1 THEN 8 ELSE 0 END)
 +(CASE WHEN CUR_HOLDING_FUND_FLAG=0 AND CUR_WMP_RISK_ASSESSMENT_LEVEL IN ('C3','C4','C5') THEN 5 ELSE 0 END) gap_score,
 7*LEAST(1,CUR_YEAR_CARRIER_ACTIVITY_PARTICIPATION_COUNT)+3*(HIST_WECOM_PRODUCT_MSG_LATEST_CLICK_TIME_ONLINE_OPS IS NOT NULL) response_score,
 7*CUR_MOBILE_NUMBER_NORMAL_FLAG+5*CUR_WECOM_AUTH_FLAG+3*(LAST_30_DAYS_APP_LOGIN_DAYS>=4) reach_score,
 10*(LAST_7_DAYS_PHONE_FACE_VISIT_COUNT>=3)+5*(LAST_30_DAYS_APP_LOGIN_DAYS=0) penalty,
 (CUR_MARKETING_BLACKLIST_FLAG=1 OR DO_NOT_DISTURB_CUST_WECOM_TAG_FLAG=1 OR CUR_AML_BLACKLIST_FLAG=1 OR CUR_CUST_LEVEL_SMART_SUSPEND_FLAG=1 OR CUR_OUR_BANK_LOAN_OVERDUE_FLAG=1 OR CUR_WMP_RISK_ASSESSMENT_LEVEL IS NULL OR CUR_WMP_RISK_ASSESSMENT_LEVEL='C1' OR (CUR_MOBILE_NUMBER_NORMAL_FLAG<>1 AND CUR_WECOM_AUTH_FLAG<>1)) excluded
 FROM b), scored AS (SELECT CUST_ID,excluded,ROUND(GREATEST(0,LEAST(100,value_score+event_score+gap_score+response_score+reach_score-penalty)),2) score FROM components)
 SELECT CASE WHEN excluded THEN 'EXCLUDED' WHEN score>=65 THEN 'HIGH' WHEN score>=40 THEN 'MEDIUM' ELSE 'LOW' END priority,COUNT(*) n FROM scored GROUP BY priority;
